mapper.sql:
select t.* from( select '待处理' validStatus, t.periodProdId, t.periodId, to_char(t.investCycle) investCycle, t.publish_type publishType, t.rateType, t.rateLower, t.rateLimit, t.rate, t.indexId, t.coefficient, t.spreadRate, t.resetType, t.termType, t.baseRule, t.dates startDate, t.dates + nvl(cast(t.investCycle as int),0) day endDate, t.p_finprod_id as finprodId, 0 branch from ( select fp.finprod_id periodProdId, '' periodId,/*期次代码*/ fpa.investment_cycle investCycle/*投资周期*/, fbri.publish_type, fbri.rate_type rateType, fbri.rate_lower *100 rateLower, fbri.rate_limit *100 rateLimit, fbri.rate *100 rate, fbri.index_id indexId, fbri.coefficient, fbri.spread_rate *100 spreadRate, fbri.reset_type resetType, fpa.term_type termType, case when fbri.publish_type = #{publishType01} then to_char(dec(fbri.rate_lower *100, 10,7)) || '~' || to_char(dec(fbri.rate_limit *100, 10,7)) when fbri.rate_type = #{calcType01} then to_char(dec(fbri.rate * 100, 10,7)) when fbri.rate_type = #{calcType02} then fbri.index_id ||'*'|| to_char(fbri.coefficient) ||'+'||to_char(dec(fbri.spread_rate*100,10,7)) end as baseRule, fp.p_finprod_id, fp.mdate, dates from fin_product fp left join fin_product_add fpa on fp.finprod_id = fpa.finprod_id
inner join PTL_PORTFOLIO_AUTHORITY ppa on fpa.PORTFOLIO_ID = ppa.PORTFOLIO_ID and ppa.USER_ID = #{userId}
left join fin_open_plan fop on fp.p_finprod_id = fop.finprod_id left join fin_base_rule_info fbri on fbri.finprod_id = fp.finprod_id,(select * from (values to_date(#{platDate}, 'yyyy-MM-dd'),to_date(#{platDate}, 'yyyy-MM-dd')+1 day,to_date(#{platDate}, 'yyyy-MM-dd')+2 day,to_date(#{platDate}, 'yyyy-MM-dd')+3 day, to_date(#{platDate}, 'yyyy-MM-dd')+4 day,to_date(#{platDate}, 'yyyy-MM-dd')+5 day,to_date(#{platDate}, 'yyyy-MM-dd')+6 day,to_date(#{platDate}, 'yyyy-MM-dd')+7 day) as t1(dates)) where fpa.deal_mode = #{dealMode10} and fbri.eff_date = ( select max(t.eff_date) from fin_base_rule_info t where t.base_rule_id = fbri.base_rule_id and t.branch = 0 and t.eff_date <= to_date(#{platDate},'yyyy-MM-dd') ) and fp.p_finprod_id is not null and fop.finprod_id is null and fbri.base_rule_type = #{baseRuleType01}
and fpa.term_type != #{termType03}
)t where t.dates <= t.mdate and not exists (select t1.finprod_id from fin_trade_product t1 where t1.finprod_id = t.periodProdId and t1.term = t.investCycle and t1.vdate = t.dates)) t
and t.finprodId in
#{item}
and t.startDate >= to_date(#{startDateBegin},'yyyy-MM-dd')
and t.startDate <= to_date(#{startDateEnd},'yyyy-MM-dd')
and t.endDate >= to_date(#{endDateBegin},'yyyy-MM-dd')
and t.endDate <= to_date(#{endDateEnd},'yyyy-MM-dd')
union all select '待处理' validStatus, t.periodProdId, t.periodId, to_char(t.investCycle) investCycle, t.publishType, t.rateType, t.rateLower, t.rateLimit, t.rate, t.indexId, t.coefficient, t.spreadRate, t.resetType, t.termType, t.baseRule, t.startDate, t.endDate, t.p_finprod_id as finprodId, 0 branch from( select fp.finprod_id periodProdId, '' periodId,/*期次代码*/ fpa.investment_cycle investCycle,/*投资周期*/ fop.open_vdate startDate,/*其次开始日*/ fop.open_vdate + nvl(cast(fpa.investment_cycle as int),0) day endDate,/*期次结束日*/ fbri.publish_type publishType, fbri.rate_type rateType, /*利率类型*/ fbri.rate_lower *100 rateLower, fbri.rate_limit *100 rateLimit, fbri.rate *100 rate, fbri.index_id indexId, fbri.coefficient, fbri.spread_rate *100 spreadRate, fbri.reset_type resetType, fpa.term_type termType, case when fbri.publish_type = #{publishType01} then to_char(dec(fbri.rate_lower *100, 10,7)) || '~' || to_char(dec(fbri.rate_limit *100, 10,7)) when fbri.rate_type = #{calcType01} then to_char(dec(fbri.rate * 100, 10,7)) when fbri.rate_type = #{calcType02} then fbri.index_id ||'*'|| to_char(fbri.coefficient) ||'+'||to_char(dec(fbri.spread_rate*100,10,7)) end as baseRule, fp.p_finprod_id from fin_product fp left join fin_product_add fpa on fp.finprod_id = fpa.finprod_id
inner join PTL_PORTFOLIO_AUTHORITY ppa on fpa.PORTFOLIO_ID = ppa.PORTFOLIO_ID and ppa.USER_ID = #{userId}
left join fin_open_plan fop on fp.p_finprod_id = fop.finprod_id left join fin_base_rule_info fbri on fbri.finprod_id = fp.finprod_id where fpa.deal_mode = #{dealMode10} and fbri.eff_date = ( select max(t.eff_date) from fin_base_rule_info t where t.base_rule_id = fbri.base_rule_id and t.branch = 0 and t.eff_date <= to_date(#{platDate},'yyyy-MM-dd') ) and fp.p_finprod_id is not null and not exists ( select t.finprod_id from fin_trade_product t where t.finprod_id = fpa.finprod_id and t.term = fpa.investment_cycle and t.vdate = fop.open_vdate ) and fop.open_vdate >= to_date(#{platDate},'yyyy-MM-dd') and fop.open_vdate <= to_date(#{platDate},'yyyy-MM-dd') + 7 day and fbri.base_rule_type = #{baseRuleType01}
and fpa.term_type != #{termType03}
) t
and t.p_finprod_id in
#{item}
and t.startDate >= to_date(#{startDateBegin},'yyyy-MM-dd')
and t.startDate <= to_date(#{startDateEnd},'yyyy-MM-dd')
and t.endDate >= to_date(#{endDateBegin},'yyyy-MM-dd')
and t.endDate <= to_date(#{endDateEnd},'yyyy-MM-dd')
